{"id": "v19/support/conjunction", "version": 1, "symbol": "conjunction", "kind": "constructor", "status": "Retained", "signature": "TERM conjunction(items: LIST[TERM]) -> TERM", "definition": "All described components apply", "not": "Does not imply temporal order", "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/character_trait", "version": 1, "symbol": "character_trait", "kind": "constructor", "status": "Retained", "signature": "TERM character_trait(property: STRING, value: STRING / NUMBER) -> TERM", "definition": "A character attribute", "not": "Not a claim about a real person", "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/property_question", "version": 1, "symbol": "property_question", "kind": "constructor", "status": "Retained", "signature": "TERM property_question(property: STRING, subject: STRING / TERM) -> TERM", "definition": "An open request for a property of a subject", "not": "Does not supply the property's value", "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/has_state", "version": 1, "symbol": "has_state", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM has_state(subject: TERM, state: STRING)", "definition": "Asserts that an entity is currently in a physical, thermal, or operational state. state must be a valid state descriptor string.", "aliases": ["in_state", "state_is"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
{"id": "v19/support/attribute_claim", "version": 4, "symbol": "attribute_claim", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM attribute_claim(subject: STRING / TERM / ATOM[platform_label], property: STRING, value: STRING / NUMBER / BOOL / TERM / ATOM[platform_label])", "definition": "Asserts that a subject possesses a named property evaluated to a specific primitive or structured value. general property attribution claim.", "aliases": ["property_value", "word_property", "has_property", "property attribution"], "dependencies": ["v19/support/subject", "v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/trace-relations-general"], "related": ["v19/support/requirement", "v19/support/has_attribute"]}
{"id": "v19/support/has_attribute", "version": 1, "symbol": "has_attribute", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM has_attribute(subject: STRING / TERM, attribute: STRING / TERM)", "definition": "Asserts that an entity, group, or person possesses a stated characteristic or attribute. general characteristic attribution.", "aliases": ["possesses_attribute"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
{"id": "v19/support/conditional", "version": 1, "symbol": "conditional", "kind": "constructor", "status": "Accepted", "signature": "TERM conditional(condition: TERM, consequence: TERM) -> TERM", "definition": "Constructs a structured conditional proposition term connecting a condition and consequence. descriptive logic structure.", "aliases": ["if_then"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/statement", "version": 3, "symbol": "statement", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM statement(fact: TERM)", "definition": "Foundational claim relation converting any descriptive TERM into an attributed, truth-evaluated assertion. universal fact assertion.", "aliases": ["assert_fact", "fact_claim", "claim_statement"], "shared_rules": ["v19/rule/trace-relations-general"], "related": ["v19/support/attribute_claim", "v19/support/has_state", "v19/support/spatial_state"]}
{"id": "v19/support/negation", "version": 1, "symbol": "negation", "kind": "constructor", "status": "Accepted", "signature": "TERM negation(target: TERM) -> TERM", "definition": "Constructs a descriptive semantic negation of a target descriptive proposition or condition term.", "not": "Check's runtime Boolean operator NOT or a speech-act decline", "aliases": ["not", "does not", "negation", "absence of"], "shared_rules": ["v19/rule/support-primitives-general"]}

{"id": "v19/support/requirement", "version": 4, "symbol": "requirement", "kind": "constructor", "status": "Retained", "signature": "TERM requirement(property: STRING, value: STRING / NUMBER / BOOL / TERM / ATOM[platform_label]) -> TERM", "definition": "Specifies a required property constraint with an expected primitive or structured value.", "not": "Does not assert an existing artifact already satisfies it", "aliases": ["constraint", "property_requirement", "structured_requirement"], "dependencies": ["v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/subject", "version": 3, "symbol": "subject", "kind": "constructor", "status": "Retained", "signature": "TERM subject(kind: STRING, qualifier?: STRING / TERM / ATOM[platform_label], location?: STRING / ATOM[country], time?: STRING) -> TERM", "definition": "Subject matter with explicit qualifiers", "not": "Does not make a factual claim about it", "dependencies": ["v19/lexical-group/country", "v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/regression_case", "version": 2, "symbol": "regression_case", "kind": "constructor", "status": "Retained", "signature": "TERM regression_case(framework: STRING / ATOM[platform_label], modifier: STRING, relation: STRING) -> TERM", "definition": "A regression scenario specifying affected framework, condition and relation", "not": "Does not invent a passing test or exact implementation", "dependencies": ["v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/change_property", "version": 1, "symbol": "change_property", "kind": "constructor", "status": "Retained", "signature": "TERM change_property(property: STRING, source: STRING, target: STRING) -> TERM", "definition": "Require target to inherit the property value from source", "not": "Not an arbitrary code patch", "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/test_condition", "version": 1, "symbol": "test_condition", "kind": "constructor", "status": "Retained", "signature": "TERM test_condition(condition: STRING, expected: BOOL) -> TERM", "definition": "A testable condition with the expected Boolean outcome", "not": "Expected outcome is not an observed result", "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/remove_literal", "version": 1, "symbol": "remove_literal", "kind": "constructor", "status": "Retained", "signature": "TERM remove_literal(text: STRING) -> TERM", "definition": "Remove occurrences of that exact literal in the stated artifact", "not": "Not remove similar markup unless specified", "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/character_trait", "version": 1, "symbol": "character_trait", "kind": "constructor", "status": "Retained", "signature": "TERM character_trait(property: STRING, value: STRING / NUMBER) -> TERM", "definition": "A character attribute", "not": "Not a claim about a real person", "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/minimum_per_period", "version": 1, "symbol": "minimum_per_period", "kind": "constructor", "status": "Retained", "signature": "TERM minimum_per_period(class: STRING, count: NUMBER, period: STRING) -> TERM", "definition": "At least count members of class in each period", "not": "Not a minimum total over the whole artifact", "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/maximum_between_stops", "version": 1, "symbol": "maximum_between_stops", "kind": "constructor", "status": "Retained", "signature": "TERM maximum_between_stops(activity: STRING, amount: NUMBER, unit: STRING) -> TERM", "definition": "Upper bound on the stated activity between successive stops", "not": "Not a limit on total daily duration", "dependencies": ["v19/support/activity"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/property_question", "version": 1, "symbol": "property_question", "kind": "constructor", "status": "Retained", "signature": "TERM property_question(property: STRING, subject: STRING / TERM) -> TERM", "definition": "An open request for a property of a subject", "not": "Does not supply the property's value", "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/naming_pattern", "version": 1, "symbol": "naming_pattern", "kind": "constructor", "status": "Accepted", "signature": "TERM naming_pattern(description: STRING, context?: STRING) -> TERM", "definition": "Constructs a descriptive naming or morphological pattern. used for rule-based or conventional naming schemes.", "aliases": ["pattern_naming"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/word_blend", "version": 1, "symbol": "word_blend", "kind": "constructor", "status": "Accepted", "signature": "TERM word_blend(base: STRING / TERM, replacement: STRING / TERM, result_name?: STRING) -> TERM", "definition": "Constructs a morphological blend or portmanteau from base and replacement terms. descriptive lexical structure.", "aliases": ["portmanteau"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/conditional", "version": 1, "symbol": "conditional", "kind": "constructor", "status": "Accepted", "signature": "TERM conditional(condition: TERM, consequence: TERM) -> TERM", "definition": "Constructs a structured conditional proposition term connecting a condition and consequence. descriptive logic structure.", "aliases": ["if_then"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/config_setting", "version": 2, "symbol": "config_setting", "kind": "constructor", "status": "Accepted", "signature": "TERM config_setting(option: STRING, section: STRING, value: STRING / NUMBER / BOOL / TERM / ATOM[platform_label]) -> TERM", "definition": "Constructs a structured representation of a configuration key-value setting within an identified section.", "not": "an active runtime configuration state or environment setting", "aliases": ["ini_setting", "config_option", "configuration_setting"], "dependencies": ["v19/lexical-group/platform_label"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/location_spec", "version": 1, "symbol": "location_spec", "kind": "constructor", "status": "Accepted", "signature": "TERM location_spec(address?: STRING, area?: STRING, city?: STRING, state?: STRING) -> TERM", "definition": "Constructs a structured geographical location specification with regional and administrative qualifiers.", "not": "a fixed atomic location descriptor in location-name or a spatial relation", "aliases": ["location_details", "geographic_location"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/rate", "version": 1, "symbol": "rate", "kind": "constructor", "status": "Accepted", "signature": "TERM rate(denominator: TERM, numerator: TERM) -> TERM", "definition": "Constructs a structured proportional rate or frequency relating a numerator measured quantity to a denominator reference quantity.", "not": "an asserted factual attribution (use attribute_claim) or bound constraint (use requirement)", "aliases": ["per_unit", "ratio"], "shared_rules": ["v19/rule/support-primitives-general"]}
{"id": "v19/support/calculation", "version": 1, "symbol": "calculation", "kind": "constructor", "status": "Accepted", "signature": "TERM calculation(inputs: LIST[TERM], operation: STRING, result?: TERM) -> TERM", "definition": "Constructs a descriptive representation of an arithmetic or algorithmic calculation step with inputs, operation identifier, and optional resulting value.", "not": "an executed runtime action or factual claim of outcome", "aliases": ["math_operation", "compute_step"], "shared_rules": ["v19/rule/support-primitives-general"]}
